export type Category = "angle" | "area" | "data" | "energy" | "frequency" | "length" | "power" | "pressure" | "speed" | "temperature" | "time" | "volume" | "weight";

export interface CategoryUnits {
  angle: AngleUnit;
  area: AreaUnit;
  data: DataUnit;
  energy: EnergyUnit;
  frequency: FrequencyUnit;
  length: LengthUnit;
  power: PowerUnit;
  pressure: PressureUnit;
  speed: SpeedUnit;
  temperature: TemperatureUnit;
  time: TimeUnit;
  volume: VolumeUnit;
  weight: WeightUnit;
}

export type CategoryUnit<C extends Category> = CategoryUnits[C];

export interface CategoryAliases {
  angle: AngleAlias;
  area: AreaAlias;
  data: DataAlias;
  energy: EnergyAlias;
  frequency: FrequencyAlias;
  length: LengthAlias;
  power: PowerAlias;
  pressure: PressureAlias;
  speed: SpeedAlias;
  temperature: TemperatureAlias;
  time: TimeAlias;
  volume: VolumeAlias;
  weight: WeightAlias;
}

export type CategoryAlias<C extends Category> = CategoryAliases[C];

